const BROWSER_HEADERS={
 'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
 'Accept':'application/json, text/plain, */*',
 'Accept-Language':'en-US,en;q=0.9',
 'Sec-Fetch-Dest':'empty',
 'Sec-Fetch-Mode':'cors',
 'Sec-Fetch-Site':'same-origin'
};

async function fetchNasaWithFallback(query, fetcher){
 let results=[];
 const seen=new Set();
 const addRows=rows=>{
  for(const row of (rows||[])){
   if(Array.isArray(row)&&row[1]&&!seen.has(row[1])){
    seen.add(row[1]);
    results.push(row);
   }
  }
 };
 try{
  const res=await fetcher('https://technology.nasa.gov/api/api/patent/'+encodeURIComponent(query.trim()),{headers:{'User-Agent':BROWSER_HEADERS['User-Agent'],'Accept':'application/json'},signal:AbortSignal.timeout(15000),redirect:'follow'});
  if(res.ok){
   const body=await res.json();
   addRows(body.results);
  }
 }catch{}

 if(results.length<20){
  const words=String(query).toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w=>w.length>2);
  const terms=[];
  for(const w of words){
   if(CONCEPT_MAP[w])terms.push(...CONCEPT_MAP[w]);
   else if(w.length>3)terms.push(w);
  }
  const uniqueTerms=[...new Set(terms)].slice(0,5);
  for(const term of uniqueTerms){
   try{
    const r=await fetcher('https://technology.nasa.gov/api/api/patent/'+encodeURIComponent(term),{headers:{'User-Agent':BROWSER_HEADERS['User-Agent'],'Accept':'application/json'},signal:AbortSignal.timeout(10000),redirect:'follow'});
    if(r.ok){
     const b=await r.json();
     addRows(b.results);
    }
   }catch{}
   if(results.length>=50)break;
  }
 }
 return results;
}

async function handlePatents(request,env,fetcher=fetch){
 const respond=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
 const bqConfigured=!!(env.BIGQUERY_PROJECT_ID||env.BIGQUERY_API_KEY||env.GOOGLE_APPLICATION_CREDENTIALS||env.BIGQUERY_TOKEN);
 if(request.method==='GET')return respond({
  enabled:!!env.LENS_API_TOKEN,
  sources:[
   {id:'google',enabled:true,label:'Google Patents (Worldwide live search · Default)'},
   {id:'all',enabled:true,label:'All Available Sources (Google Patents + NASA)'},
   {id:'nasa',enabled:true,label:'NASA Technology Transfer (Live search)'},
   {id:'bigquery',enabled:bqConfigured,label:'Google Patents Public Datasets (BigQuery)'},
   {id:'lens',enabled:!!env.LENS_API_TOKEN,label:'Lens API'}
  ]
 });
 if(request.method!=='POST')return respond({error:'Use POST'},405);
 const origin=request.headers.get('Origin')||request.headers.get('origin');
 const reqUrl=new URL(request.url);
 const host=(request.headers.get('Host')||reqUrl.host).toLowerCase();
 let originMatches=false;
 if(origin){
  try{
   const originUrl=new URL(origin);
   originMatches=(origin===reqUrl.origin)||(originUrl.host.toLowerCase()===host);
  }catch{}
 }
 if(!originMatches)return respond({error:'Same-origin requests only'},403);
 const now=Date.now(),key=request.headers.get('CF-Connecting-IP')||'local';for(const [k,v]of patentBuckets)if(now-v.at>60000)patentBuckets.delete(k);const bucket=patentBuckets.get(key)||{at:now,n:0};if(bucket.n++>=30)return respond({error:'Please wait a minute before searching again.'},429);patentBuckets.set(key,bucket);
 try{
  const raw=await request.text();if(raw.length>8000)return respond({error:'Search is too long'},413);
  const {query,source='lens',apiKey,projectId}=JSON.parse(raw);
  if(typeof query!=='string'||!query.trim()||query.length>600)return respond({error:'Enter up to 600 characters of search terms'},400);
  if(!['google','all','bigquery','lens','nasa'].includes(source))return respond({error:'Choose an integrated search source or open the external source website.'},400);
  let response;
  if(source==='all'){
   const [googleRes,nasaRes]=await Promise.allSettled([
    (async()=>{
     try{
      const qUrl='https://patents.google.com/xhr/query?url='+encodeURIComponent('q='+query.trim()+'&num=30');
      const r=await fetcher(qUrl,{headers:{'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36','Accept':'application/json'},signal:AbortSignal.timeout(15000)});
      if(!r.ok)return [];
      const body=await r.json();
      return (body.results?.cluster||[]).flatMap(c=>c.result||[]).map(x=>x.patent).filter(Boolean).map(googleRecord).filter(Boolean);
     }catch{return [];}
    })(),
    (async()=>{
     try{
      const nasaRows=await fetchNasaWithFallback(query,fetcher);
      return nasaRows.slice(0,30).map(nasaRecord).filter(Boolean);
     }catch{return [];}
    })()
   ]);
   const gRecords=googleRes.status==='fulfilled'?googleRes.value:[];
   const nRecords=nasaRes.status==='fulfilled'?nasaRes.value:[];
   const seen=new Set();
   const records=[];
   const maxLen=Math.max(gRecords.length,nRecords.length);
   for(let i=0;i<maxLen;i++){
    if(i<gRecords.length&&!seen.has(gRecords[i].id)){seen.add(gRecords[i].id);records.push(gRecords[i]);}
    if(i<nRecords.length&&!seen.has(nRecords[i].id)){seen.add(nRecords[i].id);records.push(nRecords[i]);}
   }
   return respond({records:records.slice(0,60),scope:`Unified search across all available sources (Google Patents & NASA): ${records.length} leads retrieved.`,retrievedAt:new Date().toISOString()});
  }else if(source==='nasa'){
   const results=await fetchNasaWithFallback(query, fetcher);
   const records=results.slice(0,50).map(nasaRecord).filter(Boolean);
   return respond({records,scope:`Up to 50 live NASA technology transfer records (${records.length} matching leads).`,retrievedAt:new Date().toISOString()});
  }else if(source==='google'){
   let records=[],scope='',googleStatus=0,googleErr='';
   try{
    const qUrl='https://patents.google.com/xhr/query?url='+encodeURIComponent('q='+query.trim()+'&num=30');
    response=await fetcher(qUrl,{headers:BROWSER_HEADERS,signal:AbortSignal.timeout(15000),redirect:'follow'});
    googleStatus=response.status;
    if(response.ok){
     const body=await response.json();
     const clusters=body.results?.cluster||[];
     records=clusters.flatMap(c=>c.result||[]).map(r=>r.patent).filter(Boolean).map(googleRecord).filter(Boolean);
     if(records.length)scope='Up to 30 live Google Patents worldwide matches with full text and legal status indicators.';
    }
   }catch(e){googleErr=e.message;}
   if(!records.length){
    // Fall back to NASA live search with concept expansion
    const nasaResults=await fetchNasaWithFallback(query, fetcher);
    records=nasaResults.slice(0,50).map(nasaRecord).filter(Boolean);
    scope=records.length?`Retrieved from NASA Technology Transfer live API (Google: ${googleStatus||googleErr}).`:`Search returned 0 leads (Google: ${googleStatus||googleErr}). Try another term or open Google Patents directly.`;
   }
   return respond({records,scope,retrievedAt:new Date().toISOString()});
  }else if(source==='bigquery'){
   const bqProject=projectId||env.BIGQUERY_PROJECT_ID;
   const bqToken=apiKey||env.BIGQUERY_TOKEN||env.BIGQUERY_API_KEY;
   if(!bqProject)return respond({error:'BigQuery search requires a Google Cloud project ID. Enter your project ID in BigQuery settings or configure BIGQUERY_PROJECT_ID.'},503);
   const bqSql=`SELECT publication_number, country_code, (SELECT text FROM UNNEST(title_localized) WHERE language = 'en' LIMIT 1) as title, (SELECT text FROM UNNEST(abstract_localized) WHERE language = 'en' LIMIT 1) as abstract, publication_date FROM \`patents-public-data.patents.publications\` WHERE (LOWER((SELECT text FROM UNNEST(title_localized) WHERE language = 'en' LIMIT 1)) LIKE @term OR LOWER((SELECT text FROM UNNEST(abstract_localized) WHERE language = 'en' LIMIT 1)) LIKE @term) ORDER BY publication_date DESC LIMIT 30`;
   const bqUrl=`https://bigquery.googleapis.com/bigquery/v2/projects/${encodeURIComponent(bqProject)}/queries${bqToken&&!bqToken.startsWith('Bearer')&&!bqToken.includes('.')?'?key='+encodeURIComponent(bqToken):''}`;
   const bqHeaders={'Content-Type':'application/json'};
   if(bqToken&&(bqToken.startsWith('Bearer')||bqToken.includes('.')))bqHeaders.Authorization=bqToken.startsWith('Bearer')?bqToken:'Bearer '+bqToken;
   response=await fetcher(bqUrl,{method:'POST',headers:bqHeaders,body:JSON.stringify({query:bqSql,queryParameters:[{name:'term',parameterType:{type:'STRING'},parameterValue:{value:'%'+query.trim().toLowerCase()+'%'}}],useLegacySql:false}),signal:AbortSignal.timeout(30000)});
   if(!response.ok)return respond({error:'BigQuery provider returned HTTP '+response.status+'. Check GCP project, API access or quota.'},502);
   const body=await response.json();
   const rows=body.rows||[];
   const schema=body.schema?.fields?.map(f=>f.name)||['publication_number','country_code','title','abstract','publication_date'];
   const records=rows.map(r=>{const obj={};(r.f||[]).forEach((val,i)=>{obj[schema[i]]=val?.v;});return bigqueryRecord(obj);}).filter(Boolean);
   return respond({records,scope:'Google Patents Public Dataset records retrieved from BigQuery patents-public-data.patents.publications.',retrievedAt:new Date().toISOString()});
  }else{
   const token=typeof apiKey==='string'?apiKey.trim():env.LENS_API_TOKEN;
   if(!token)return respond({error:'Lens requires an approved API token. Enter yours in source settings or choose another source.'},503);
   if(token.length>4096||/[\r\n]/.test(token))return respond({error:'Invalid Lens token'},400);
   response=await fetcher('https://api.lens.org/patent/search',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify({query:{match:{full_text:query}},size:30}),signal:AbortSignal.timeout(30000),redirect:'error'});
   if(!response.ok)return respond({error:'Patent provider returned HTTP '+response.status+'. Check availability, API access or quota.'},502);
   const body=await response.json();
   const records=(body.data||[]).map(lensRecord).filter(Boolean);
   return respond({records,scope:'First 30 live Lens matches; coverage varies.',retrievedAt:new Date().toISOString()});
  }
 }catch{
  return respond({error:'Fresh source search could not complete. Retry or choose another source.'},502);
 }
}

function providers(env){return [{id:'local-server',label:'Local Ollama on this server',model:env.OLLAMA_MODEL,enabled:!!env.OLLAMA_MODEL},{id:'openai',label:'OpenAI',model:env.OPENAI_MODEL,enabled:!!(env.OPENAI_API_KEY&&env.OPENAI_MODEL)},{id:'anthropic',label:'Anthropic',model:env.ANTHROPIC_MODEL,enabled:!!(env.ANTHROPIC_API_KEY&&env.ANTHROPIC_MODEL)},{id:'deepseek',label:'DeepSeek',model:env.DEEPSEEK_MODEL,enabled:!!(env.DEEPSEEK_API_KEY&&env.DEEPSEEK_MODEL)},{id:'gemini',label:'Gemini',model:env.GEMINI_MODEL,enabled:!!(env.GEMINI_API_KEY&&env.GEMINI_MODEL)},{id:'compatible',label:'OpenAI-compatible service',model:env.COMPATIBLE_MODEL,enabled:!!(env.COMPATIBLE_BASE_URL&&env.COMPATIBLE_MODEL)}].map(({id,label,model,enabled})=>({id,label,model:enabled?model:null,enabled}));}
function buildRequest(provider,env,msg,stage){const headers={'Content-Type':'application/json'};if(provider==='local-server')return {url:'http://127.0.0.1:11434/api/chat',headers,body:{model:env.OLLAMA_MODEL,messages:msg.map((m,i)=>stage==='plan'&&i===1?{...m,content:m.content+'\nReturn sections as an object keyed by the exact section titles, with plain-text string values, matching the output schema.'}:m),stream:false,format:outputSchema(stage),think:false,options:{num_ctx:16384,num_predict:10000}},model:env.OLLAMA_MODEL};if(provider==='openai'){headers.Authorization='Bearer '+env.OPENAI_API_KEY;return {url:'https://api.openai.com/v1/responses',headers,body:{model:env.OPENAI_MODEL,input:msg,max_output_tokens:10000,store:false},model:env.OPENAI_MODEL};}if(provider==='anthropic'){headers['x-api-key']=env.ANTHROPIC_API_KEY;headers['anthropic-version']='2026-10-21';return {url:'https://api.anthropic.com/v1/messages',headers,body:{model:env.ANTHROPIC_MODEL,system:msg[0].content,messages:msg.slice(1),max_tokens:12000},model:env.ANTHROPIC_MODEL};}if(provider==='deepseek'){headers.Authorization='Bearer '+env.DEEPSEEK_API_KEY;return {url:'https://api.deepseek.com/chat/completions',headers,body:{model:env.DEEPSEEK_MODEL,messages:msg,stream:false,response_format:{type:'json_object'}},model:env.DEEPSEEK_MODEL};}if(provider==='gemini'){headers['x-goog-api-key']=env.GEMINI_API_KEY;return {url:`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(env.GEMINI_MODEL)}:generateContent`,headers,body:{systemInstruction:{parts:[{text:msg[0].content}]},contents:[{role:'user',parts:[{text:msg[1].content}]}],generationConfig:{responseMimeType:'application/json',maxOutputTokens:12000}},model:env.GEMINI_MODEL};}if(provider==='compatible'){const base=new URL(env.COMPATIBLE_BASE_URL);if(base.protocol!=='https:'&&!(['localhost','127.0.0.1','[::1]'].includes(base.hostname)&&base.protocol==='http:'))throw Error('The configured compatible endpoint must use HTTPS or loopback HTTP.');if(base.username||base.password||base.search||base.hash)throw Error('Invalid compatible base URL.');if(env.COMPATIBLE_API_KEY)headers.Authorization='Bearer '+env.COMPATIBLE_API_KEY;return {url:base.href.replace(/\/$/,'')+'/chat/completions',headers,body:{model:env.COMPATIBLE_MODEL,messages:msg,stream:false},model:env.COMPATIBLE_MODEL};}throw Error('Unsupported provider');}
function extractText(provider,data){if(provider==='anthropic')return (data.content||[]).filter(c=>c.type==='text').map(c=>c.text).join('\n');if(provider==='local-server')return data.message?.content||'';if(provider==='openai')return (data.output||[]).flatMap(i=>i.content||[]).filter(c=>c.type==='output_text').map(c=>c.text).join('\n');if(provider==='gemini')return (data.candidates?.[0]?.content?.parts||[]).map(p=>p.text||'').join('\n');return data.choices?.[0]?.message?.content||'';}
const json=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const buckets=new Map();
async function handleAI(request,env,fetcher=fetch){const url=new URL(request.url);if(url.pathname==='/api/patents')return handlePatents(request,env,fetcher);if(url.pathname==='/api/ollama/models'){if(env.LOCAL_RUNTIME!=='true'||request.method!=='GET')return json({error:'Local discovery is only available on the local app server.'},404);try{const response=await fetcher('http://127.0.0.1:11434/api/tags',{signal:AbortSignal.timeout(5000)});if(!response.ok)throw Error();const data=await response.json();return json({models:(data.models||[]).map(m=>({name:m.name,size:m.size})),transport:'local-server'});}catch{return json({error:'Ollama is not reachable on this computer. Start Ollama and retry.'},503);}}if(url.pathname==='/api/config'&&request.method==='GET')return json({providers:providers(env),webResearch:false});if(url.pathname!=='/api/ai')return json({error:'Not found'},404);if(request.method!=='POST')return json({error:'Use POST'},405);
const origin=request.headers.get('Origin')||request.headers.get('origin');
const host=(request.headers.get('Host')||url.host).toLowerCase();
let originMatches=false;
if(origin){
 try{
  const originUrl=new URL(origin);
  originMatches=(origin===url.origin)||(originUrl.host.toLowerCase()===host);
 }catch{}
}
if(!originMatches)return json({error:'This endpoint only accepts requests from this application.'},403);if(!request.headers.get('content-type')?.includes('application/json'))return json({error:'JSON required'},415);const client=request.headers.get('CF-Connecting-IP')||'local';const now=Date.now();for(const [k,v]of buckets)if(now-v.start>60000)buckets.delete(k);const bucket=buckets.get(client)||{start:now,count:0};if(bucket.count>=8)return json({error:'Please wait a minute before asking the assistant again.'},429);bucket.count++;buckets.set(client,bucket);try{const raw=await request.text();if(raw.length>120000)return json({error:'Project context is too large. Shorten the evidence notes.'},413);const {provider,stage,data,credentials}=JSON.parse(raw);env=connectionEnv(provider,env,credentials);if(!providers(env).some(p=>p.id===provider&&p.enabled))return json({error:'This AI service is not configured by the site owner. Enter your API key and model in Connect AI, or choose a local connection.'},503);if(!data||typeof data!=='object')return json({error:'Project input required'},400);const req=buildRequest(provider,env,messages(stage,data),stage);const response=await fetcher(req.url,{method:'POST',headers:req.headers,body:JSON.stringify(req.body),signal:AbortSignal.timeout(stage==='plan'?330000:150000),redirect:'error'});if(!response.ok)return json({error:`The AI provider returned HTTP ${response.status}. Check model access, quota, and server settings.`},502);const body=await response.json();const text=extractText(provider,body);if(!text)throw Error('The model returned no text. Check the selected model or try again.');const result=parseAI(text,stage);return json({result,provider,model:req.model,at:new Date().toISOString()});}catch(error){return json({error:error.name==='TimeoutError'?'The model took too long. Try a smaller task or another provider.':error instanceof SyntaxError?'Invalid request or provider response.':String(error.message||'AI request failed').slice(0,300)},400);}}

function connectionEnv(provider,env,credentials){
 if(!credentials)return env;
 if(!credentials||typeof credentials!=='object')throw Error('Invalid connection settings');
 const model=typeof credentials.model==='string'?credentials.model.trim():'';
 if(!model||model.length>200||/[\r\n]/.test(model))throw Error('Enter a model identifier.');
 if(provider==='local-server'&&env.LOCAL_RUNTIME==='true')return {...env,OLLAMA_MODEL:model};
 const prefix={openai:'OPENAI',anthropic:'ANTHROPIC',deepseek:'DEEPSEEK',gemini:'GEMINI'}[provider];
 if(!prefix)throw Error('This provider does not accept session credentials through the gateway.');
 const key=typeof credentials.apiKey==='string'?credentials.apiKey.trim():'';
 if(!key||key.length>4096||/[\r\n]/.test(key))throw Error('Enter a valid API key.');
 return {...env,[prefix+'_API_KEY']:key,[prefix+'_MODEL']:model};
}

const ASSETS={"/404.html":{"type":"text/html; charset=utf-8","base64":""},"/ai-client.js":{"type":"text/javascript; charset=utf-8","base64":""},"/core.js":{"type":"text/javascript; charset=utf-8","base64":""},"/explorer.html":{"type":"text/html; charset=utf-8","base64":""},"/icon-192.png":{"type":"image/png","base64":""},"/icon-512.png":{"type":"image/png","base64":""},"/icon.svg":{"type":"image/svg+xml","base64":""},"/index.html":{"type":"text/html; charset=utf-8","base64":""},"/manifest.webmanifest":{"type":"application/manifest+json","base64":""},"/patents.js":{"type":"text/javascript; charset=utf-8","base64":""},"/prompts.js":{"type":"text/javascript; charset=utf-8","base64":""},"/sw.js":{"type":"text/javascript; charset=utf-8","base64":""},"/venture-core.js":{"type":"text/javascript; charset=utf-8","base64":""},"/venture.css":{"type":"text/css; charset=utf-8","base64":""},"/venture.js":{"type":"text/javascript; charset=utf-8","base64":""},"/word-export.js":{"type":"text/javascript; charset=utf-8","base64":""}};
export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname.startsWith('/api/'))return handleAI(request,env);if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});const asset=ASSETS[url.pathname==='/'?'/index.html':url.pathname];if(!asset)return new Response('Not found',{status:404});const bytes=Uint8Array.from(atob(asset.base64),c=>c.charCodeAt(0));return new Response(request.method==='HEAD'?null:bytes,{headers:{'Content-Type':asset.type,'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin'}});}};
